message.content:
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?company ?num
WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?label ;
           sdk:hasNumberOfEmployees ?num .
  FILTER(CONTAINS(LCASE(STR(?label)), "steel"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?name
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasCertificate ?cert ;
                rdfs:label ?name .
  ?cert a sdk:ISO9001 ;
        rdfs:label "ISO 9001" .
  FILTER(langMatches(lang(?name), "en"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?text WHERE {
  ?naics sdk:hasNAICSCodeValue ?code ;
         sdk:hasNAICSTextValue ?text .
  FILTER(REPLACE(STR(?code), "\\.0$", "") = "332996")
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?code
WHERE {
  ?classifier sdk:hasNAICSTextValue ?text ;
              sdk:hasNAICSCodeValue ?code .
  FILTER(CONTAINS(LCASE(STR(?text)), "pipe and pipe fitting"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>

SELECT ?manufacturer ?name ?businessDescription
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?name ;
                iof-core:describedBy ?desc .
  ?desc a sdk:BusinessDescription ;
        iof-scro:hasTextValue ?businessDescription .
  FILTER(CONTAINS(LCASE(STR(?name)), "fabrication"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?latitude
WHERE {
  ?site a sdk:GeospatialLocation ;
        sdk:locatedInCity ?city ;
        sdk:hasSpatialCoordinates ?coords .
  ?city rdfs:label ?cityName .
  ?coords sdk:hasLatitudeValue ?latitude .
  FILTER(CONTAINS(LCASE(STR(?cityName)), "springfield"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?stateName
WHERE {
  ?city a sdk:City ;
        rdfs:label ?cityName ;
        sdk:locatedInState ?state .
  ?state a sdk:State ;
         rdfs:label ?stateName .
  FILTER(CONTAINS(LCASE(STR(?cityName)), "san "))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?naicsCode
WHERE {
  ?m a iof-core:Manufacturer ;
     rdfs:label ?name ;
     sdk:hasPrimaryNAICSClassifier ?naics .
  ?naics sdk:hasNAICSCodeValue ?naicsCode .
  FILTER(CONTAINS(LCASE(STR(?name)), "precision"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?industry ?industryLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerName ;
                sdk:suppliesToIndustry ?industry .
  FILTER(CONTAINS(LCASE(STR(?manufacturerName)), "automation"))
  OPTIONAL { ?industry rdfs:label ?industryLabel }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?product ?productLabel
WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?companyName ;
           sdk:manufactures ?product .
  ?product a iof-core:MaterialProduct .
  FILTER(CONTAINS(LCASE(STR(?companyName)), "tooling"))
  OPTIONAL { ?product rdfs:label ?productLabel . }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?company ?companyLabel ?processCapability ?processCapabilityLabel
WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?companyLabel ;
           sdk:hasProcessCapability ?processCapability .
  OPTIONAL { ?processCapability rdfs:label ?processCapabilityLabel }
  FILTER(CONTAINS(LCASE(STR(?companyLabel)), "aerospace"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?capability ?capabilityLabel
WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?companyName ;
           sdk:hasMaterialCapability ?capability .
  FILTER(CONTAINS(LCASE(STR(?companyName)), "metal"))
  OPTIONAL { ?capability rdfs:label ?capabilityLabel . }
}
ORDER BY ?capabilityLabel ?capability

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?certificate ?certificateLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                sdk:hasCertificate ?certificate .
  OPTIONAL { ?certificate rdfs:label ?certificateLabel . }
  FILTER(CONTAINS(LCASE(STR(?manufacturerLabel)), "plastics"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?city ?cityLabel WHERE {
  ?org a iof-core:Manufacturer ;
       rdfs:label ?orgLabel ;
       sdk:organizationLocatedIn ?site .
  ?site a sdk:GeospatialLocation ;
        sdk:locatedInCity ?city .
  ?city a sdk:City ;
        rdfs:label ?cityLabel .
  FILTER(CONTAINS(LCASE(STR(?orgLabel)), "robotics"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?state ?stateLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  OPTIONAL { ?state rdfs:label ?stateLabel . }
  FILTER(CONTAINS(LCASE(STR(?manufacturerLabel)), "valve"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?zip
WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?name ;
           sdk:organizationLocatedIn ?site .
  FILTER(CONTAINS(LCASE(STR(?name)), "casting"))
  ?site sdk:hasZIPcode ?zipNode .
  ?zipNode sdk:hasIntegerValue ?zip .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?latitude ?longitude
WHERE {
  ?org a iof-core:Manufacturer ;
       rdfs:label ?orgName ;
       sdk:organizationLocatedIn ?site .
  FILTER(CONTAINS(LCASE(STR(?orgName)), "surface finish"))
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords sdk:hasLatitudeValue ?latitude ;
          sdk:hasLongitudeValue ?longitude .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?city ?cityLabel (COUNT(DISTINCT ?manufacturer) AS ?manufacturerCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  OPTIONAL { ?city rdfs:label ?cityLabel . }
}
GROUP BY ?city ?cityLabel
ORDER BY ?cityLabel ?city

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?industry ?industryLabel (COUNT(DISTINCT ?m) AS ?manufacturerCount)
WHERE {
  ?m a iof-core:Manufacturer ;
     sdk:suppliesToIndustry ?industry .
  OPTIONAL { ?industry rdfs:label ?industryLabel . }
}
GROUP BY ?industry ?industryLabel
ORDER BY ?industryLabel ?industry

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?state ?stateLabel (SUM(?orgEmp) AS ?totalEmployees)
WHERE {
  {
    SELECT ?state ?org (MAX(?emp) AS ?orgEmp)
    WHERE {
      ?org a iof-core:Manufacturer ;
           sdk:hasNumberOfEmployees ?empLit ;
           sdk:organizationLocatedIn ?site .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
      BIND(xsd:integer(REPLACE(STR(?empLit), ",", "")) AS ?emp)
    }
    GROUP BY ?state ?org
  }
  OPTIONAL { ?state rdfs:label ?stateLabel . }
}
GROUP BY ?state ?stateLabel
ORDER BY ?stateLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT ?cert (COUNT(DISTINCT ?org) AS ?manufacturerCount)
WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:hasCertificate ?cert .
}
GROUP BY ?cert
ORDER BY ?cert

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT ?naics ?code ?text (COUNT(DISTINCT ?m) AS ?manufacturerCount)
WHERE {
  ?m a iof-core:Manufacturer ;
     sdk:hasPrimaryNAICSClassifier ?naics .
  OPTIONAL { ?naics sdk:hasNAICSCodeValue ?code . }
  OPTIONAL { ?naics sdk:hasNAICSTextValue ?text . }
}
GROUP BY ?naics ?code ?text
ORDER BY ?naics

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT ?manufacturer (COUNT(DISTINCT ?product) AS ?productCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL {
    ?manufacturer sdk:manufactures ?product .
    ?product a iof-core:MaterialProduct .
  }
}
GROUP BY ?manufacturer
ORDER BY ?manufacturer

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT ?manufacturer (COUNT(DISTINCT ?cap) AS ?totalCapabilities)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL {
    { ?manufacturer sdk:hasProcessCapability ?cap . }
    UNION
    { ?manufacturer sdk:hasMaterialCapability ?cap . }
  }
}
GROUP BY ?manufacturer
ORDER BY ?manufacturer

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT (COUNT(DISTINCT ?m) AS ?count)
WHERE {
  ?m a iof-core:Manufacturer .
  FILTER NOT EXISTS {
    ?m iof-core:describedBy ?desc .
    ?desc a sdk:BusinessDescription .
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

ASK {
  ?m a iof-core:Manufacturer ;
     sdk:hasCertificate ?cert .
  ?cert rdfs:label "ISO 9001" .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

ASK {
  ?m a iof-core:Manufacturer ;
     sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state a sdk:State ;
         rdfs:label ?stateLabel .
  FILTER(?stateLabel = "Texas")
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?reInd ;
                sdk:suppliesToIndustry ?utInd .
  ?reInd a sdk:RenewableEnergyIndustry .
  ?utInd a sdk:UtilitiesIndustry .
  FILTER(?reInd != ?utInd)
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

ASK {
  ?m a iof-core:Manufacturer ;
     rdfs:label ?name ;
     sdk:hasPrimaryNAICSClassifier ?naics .
  FILTER(CONTAINS(LCASE(STR(?name)), "pipe"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

ASK {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:manufactures ?product .
  ?product rdfs:label ?productLabel .
  FILTER(CONTAINS(LCASE(STR(?productLabel)), "valve"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

ASK WHERE {
  ?m a iof-core:Manufacturer ;
     sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city rdfs:label ?cityLabel ;
        sdk:locatedInState ?state .
  ?state rdfs:label ?stateLabel .
  FILTER(LCASE(STR(?cityLabel)) = "phoenix")
  FILTER(LCASE(STR(?stateLabel)) = "arizona")
  FILTER NOT EXISTS { ?m sdk:hasCertificate ?cert }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>

SELECT DISTINCT ?site WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:organizationLocatedIn ?site .
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords sdk:hasLatitudeValue ?lat ;
          sdk:hasLongitudeValue ?long .
}
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasMaterialCapability ?bronzeCap, ?steelCap .
  ?bronzeCap a sdk:BronzeProcessingCapability .
  ?steelCap a sdk:SteelProcessingCapability .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT ?manufacturer
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  FILTER NOT EXISTS { ?manufacturer sdk:hasCertificate ?cert . }
}
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>

ASK {
  ?m a iof-core:Manufacturer ;
     rdfs:label ?name ;
     iof-core:describedBy ?desc .
  FILTER(CONTAINS(LCASE(STR(?name)), "coating")) .
  ?desc a sdk:BusinessDescription ;
        iof-scro:hasTextValue ?text .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?name
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?name .
  FILTER regex(?name, "^A")
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT ?naics ?text ?code
WHERE {
  ?naics sdk:hasNAICSTextValue ?text .
  FILTER(CONTAINS(LCASE(STR(?text)), "pipe")) .
  OPTIONAL { ?naics sdk:hasNAICSCodeValue ?code . }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:hasZIPcode ?zip .
  ?zip sdk:hasIntegerValue ?zipVal .
  FILTER(STR(?zipVal) = "85027.0")
  OPTIONAL { ?manufacturer rdfs:label ?label }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?manufacturer ?label ?latitude
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  OPTIONAL { ?manufacturer rdfs:label ?label . }
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords sdk:hasLatitudeValue ?latitude .
  FILTER(xsd:float(?latitude) > 45.0)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT DISTINCT ?manufacturer ?site ?lon
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords sdk:hasLongitudeValue ?lon .
  FILTER (?lon < 100.0)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?industry ?industryLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?industry .
  ?industry a sdk:UtilitiesIndustry .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  OPTIONAL { ?industry rdfs:label ?industryLabel . }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?product ?productLabel ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:manufactures ?product ;
                rdfs:label ?manufacturerLabel .
  ?product a iof-core:MaterialProduct ;
           rdfs:label ?productLabel .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?name
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?name .
  FILTER(STRLEN(STR(?name)) > 8)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?city ?cityLabel (COUNT(DISTINCT ?manufacturer) AS ?manufacturerCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  OPTIONAL { ?city rdfs:label ?cityLabel . }
}
GROUP BY ?city ?cityLabel
ORDER BY DESC(?manufacturerCount)
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?industry ?label (COUNT(DISTINCT ?m) AS ?supplierCount)
WHERE {
  ?m a iof-core:Manufacturer ;
     sdk:suppliesToIndustry ?industry .
  OPTIONAL { ?industry rdfs:label ?label }
}
GROUP BY ?industry ?label
ORDER BY DESC(?supplierCount)
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?certificateType ?certificateTypeLabel (COUNT(DISTINCT ?m) AS ?manufacturerCount)
WHERE {
  ?m a iof-core:Manufacturer ;
     sdk:hasCertificate ?cert .
  ?cert a ?certificateType .
  OPTIONAL { ?certificateType rdfs:label ?certificateTypeLabel }
}
GROUP BY ?certificateType ?certificateTypeLabel
ORDER BY DESC(?manufacturerCount)
LIMIT 1

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?product ?label (COUNT(DISTINCT ?m) AS ?manufacturerCount)
WHERE {
  ?m a iof-core:Manufacturer ;
     sdk:manufactures ?product .
  ?product a iof-core:MaterialProduct .
  OPTIONAL { ?product rdfs:label ?label }
}
GROUP BY ?product ?label
ORDER BY DESC(?manufacturerCount)
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX bfo: <http://purl.obolibrary.org/obo/>

SELECT ?naicsClassifier ?naicsCode ?naicsText (COUNT(DISTINCT ?m) AS ?manufacturerCount)
WHERE {
  ?m a iof-core:Manufacturer ;
     sdk:hasPrimaryNAICSClassifier ?naicsClassifier .
  OPTIONAL { ?naicsClassifier sdk:hasNAICSCodeValue ?naicsCode . }
  OPTIONAL { ?naicsClassifier sdk:hasNAICSTextValue ?naicsText . }
}
GROUP BY ?naicsClassifier ?naicsCode ?naicsText
ORDER BY DESC(?manufacturerCount)
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT DISTINCT ?manufacturer ?naicsText
WHERE {
