PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>

SELECT DISTINCT ?org ?orgLabel ?site ?city ?cityLabel ?state ?stateLabel ?address
WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:organizationLocatedIn ?site .
  OPTIONAL { ?org rdfs:label ?orgLabel . }

  OPTIONAL {
    ?site sdk:hasPostalAddress ?addr .
    ?addr iof-scro:hasTextValue ?address .
  }

  OPTIONAL {
    ?site sdk:locatedInCity ?city .
    OPTIONAL { ?city rdfs:label ?cityLabel . }
    OPTIONAL {
      ?city sdk:locatedInState ?state .
      OPTIONAL { ?state rdfs:label ?stateLabel . }
    }
  }

  FILTER(
    (BOUND(?orgLabel) && CONTAINS(LCASE(?orgLabel), "new york")) ||
    (BOUND(?address) && CONTAINS(LCASE(?address), "new york")) ||
    (BOUND(?cityLabel) && CONTAINS(LCASE(?cityLabel), "new york")) ||
    (BOUND(?stateLabel) && CONTAINS(LCASE(?stateLabel), "new york"))
  )
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?state ?stateLabel ?manufacturer ?manufacturerLabel ?employees
WHERE {
  {
    SELECT ?state ?stateLabel ?manufacturer ?manufacturerLabel ?employees ?rank
    WHERE {
      ?manufacturer a iof-core:Manufacturer ;
                    rdfs:label ?manufacturerLabel ;
                    sdk:hasNumberOfEmployees ?emp ;
                    sdk:organizationLocatedIn ?site .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
      ?state rdfs:label ?stateLabel .
      BIND(xsd:integer(REPLACE(STR(?emp), ",", "")) AS ?employees)

      {
        SELECT ?state ?manufacturer (COUNT(?other) AS ?higherCount)
        WHERE {
          ?manufacturer a iof-core:Manufacturer ;
                        sdk:hasNumberOfEmployees ?empA ;
                        sdk:organizationLocatedIn ?siteA .
          ?siteA sdk:locatedInCity ?cityA .
          ?cityA sdk:locatedInState ?state .

          ?other a iof-core:Manufacturer ;
                 sdk:hasNumberOfEmployees ?empB ;
                 sdk:organizationLocatedIn ?siteB .
          ?siteB sdk:locatedInCity ?cityB .
          ?cityB sdk:locatedInState ?state .

          BIND(xsd:integer(REPLACE(STR(?empA), ",", "")) AS ?empAInt)
          BIND(xsd:integer(REPLACE(STR(?empB), ",", "")) AS ?empBInt)

          FILTER(?empBInt > ?empAInt || (?empBInt = ?empAInt && STR(?other) < STR(?manufacturer)))
        }
        GROUP BY ?state ?manufacturer
      }
      BIND(?higherCount + 1 AS ?rank)
    }
  }
  FILTER(?rank <= 3)
}
ORDER BY ?stateLabel ?rank ?manufacturerLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?industry ?industryLabel ?manufacturer ?manufacturerLabel ?employeeCount
WHERE {
  {
    SELECT ?industry (AVG(?empClean) AS ?avgEmp)
    WHERE {
      ?m a iof-core:Manufacturer ;
         sdk:suppliesToIndustry ?industry ;
         sdk:hasNumberOfEmployees ?empLit .
      BIND(xsd:integer(REPLACE(STR(?empLit), ",", "")) AS ?empClean)
    }
    GROUP BY ?industry
  }
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?industry ;
                sdk:hasNumberOfEmployees ?empLit2 .
  BIND(xsd:integer(REPLACE(STR(?empLit2), ",", "")) AS ?employeeCount)
  FILTER(?employeeCount > ?avgEmp)
  OPTIONAL { ?industry rdfs:label ?industryLabel . }
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
}
ORDER BY ?industry ?manufacturer

