  ?capabilityClass rdfs:subClassOf+ ?subtractive .
  ?subtractive rdfs:label "Subtractive Manufacturing" .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  OPTIONAL { ?capabilityClass rdfs:label ?capabilityClassLabel . }
}

