                rdfs:label ?manufacturerLabel ;
                sdk:hasProcessCapability ?turnCap ;
                sdk:hasProcessCapability ?millCap .
  ?turnCap a sdk:TurningCapability .
  ?millCap a sdk:MillingCapability .
