PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?m ?label
WHERE {
  ?m a iof-core:Manufacturer .
  OPTIONAL { ?m rdfs:label ?label . }
  FILTER NOT EXISTS {
    ?m sdk:organizationLocatedIn/sdk:hasPostalAddress ?addr .
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  OPTIONAL { ?manufacturer rdfs:label ?label . }
  FILTER NOT EXISTS { ?site sdk:hasSpatialCoordinates ?coords1 . ?coords1 sdk:hasLatitudeValue ?lat . }
  FILTER NOT EXISTS { ?site sdk:hasSpatialCoordinates ?coords2 . ?coords2 sdk:hasLongitudeValue ?lon . }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label . }
  FILTER NOT EXISTS {
    ?manufacturer iof-core:describedBy ?desc .
    ?desc a sdk:BusinessDescription .
  }
}
ORDER BY COALESCE(?label, STR(?manufacturer))

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer sdk:manufactures ?product . }
  OPTIONAL { ?manufacturer rdfs:label ?label . }
}
GROUP BY ?manufacturer ?label
HAVING (COUNT(DISTINCT ?product) = 0)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label
WHERE {
  {
    SELECT ?manufacturer ?label (COUNT(DISTINCT ?industry) AS ?numIndustries)
    WHERE {
      ?manufacturer a iof-core:Manufacturer .
      OPTIONAL { ?manufacturer sdk:suppliesToIndustry ?industry . }
      OPTIONAL { ?manufacturer rdfs:label ?label . }
    }
    GROUP BY ?manufacturer ?label
  }
  FILTER(?numIndustries = 0)
}
ORDER BY ?numIndustries ?label

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label . }
  FILTER NOT EXISTS {
    ?manufacturer sdk:organizationLocatedIn ?site .
    ?site sdk:hasZIPcode ?zip .
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label (COUNT(DISTINCT ?cap) AS ?numProcessCapabilities)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label . }
  OPTIONAL { ?manufacturer sdk:hasProcessCapability ?cap . }
}
GROUP BY ?manufacturer ?label
HAVING (COUNT(DISTINCT ?cap) = 0)
ORDER BY ?numProcessCapabilities ?label ?manufacturer

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label (COUNT(DISTINCT ?cap) AS ?capCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label . }
  OPTIONAL { ?manufacturer sdk:hasMaterialCapability ?cap . }
}
GROUP BY ?manufacturer ?label
HAVING (COUNT(DISTINCT ?cap) = 0)
ORDER BY ASC(?capCount) ASC(?label) ASC(?manufacturer)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasCertificate ?cert ;
                sdk:suppliesToIndustry ?aeroIndustry, ?autoIndustry ;
                rdfs:label ?manufacturerLabel .
  ?cert a sdk:ISO9001 .
  ?aeroIndustry rdfs:label "Aerospace" .
  ?autoIndustry rdfs:label "Automotive" .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?industry ;
                sdk:hasProcessCapability ?cap ;
                sdk:hasNumberOfEmployees ?empLit .
  ?industry a sdk:RenewableEnergyIndustry .
  ?cap a ?capClass .
  ?capClass rdfs:subClassOf* sdk:CoatingCapability .
  BIND(REPLACE(STR(?empLit), ",", "") AS ?empNoComma)
  BIND(xsd:integer(?empNoComma) AS ?empCount)
  FILTER(?empCount > 200)
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel }
}
ORDER BY ?manufacturerLabel

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?state ?stateLabel ?manufacturer ?manufacturerLabel ?productCount
WHERE {
  {
    SELECT ?state ?manufacturer (COUNT(DISTINCT ?prod) AS ?productCount)
    WHERE {
      ?manufacturer a iof-core:Manufacturer ;
                    sdk:organizationLocatedIn ?site ;
                    sdk:manufactures ?prod ;
                    sdk:hasCertificate ?cert .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
    }
    GROUP BY ?state ?manufacturer
  }
  FILTER NOT EXISTS {
    {
      SELECT ?state2 ?manufacturer2 (COUNT(DISTINCT ?prod2) AS ?productCount2)
      WHERE {
        ?manufacturer2 a iof-core:Manufacturer ;
                        sdk:organizationLocatedIn ?site2 ;
                        sdk:manufactures ?prod2 ;
                        sdk:hasCertificate ?cert2 .
        ?site2 sdk:locatedInCity ?city2 .
        ?city2 sdk:locatedInState ?state2 .
      }
      GROUP BY ?state2 ?manufacturer2
    }
    FILTER(?state2 = ?state && ?productCount2 > ?productCount)
  }
  OPTIONAL { ?state rdfs:label ?stateLabel . }
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
}
ORDER BY ?state ?manufacturer

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
