                rdfs:label ?label .
  FILTER EXISTS { ?manufacturer sdk:hasProcessCapability ?pc . }
  FILTER EXISTS { ?manufacturer sdk:hasMaterialCapability ?mc . }
  {
    SELECT ?manufacturer
    WHERE {
      { ?manufacturer sdk:hasProcessCapability ?cap . }
      UNION
      { ?manufacturer sdk:hasMaterialCapability ?cap . }
    }
    GROUP BY ?manufacturer
    HAVING (COUNT(DISTINCT ?cap) = 4)
  }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label .

  FILTER EXISTS {
    ?manufacturer sdk:suppliesToIndustry ?re .
    ?re a sdk:RenewableEnergyIndustry .
  }

  FILTER EXISTS {
    ?manufacturer sdk:suppliesToIndustry ?ut .
    ?ut a sdk:UtilitiesIndustry .
  }

  FILTER NOT EXISTS {
    ?manufacturer sdk:suppliesToIndustry ?ind .
    ?ind a ?t .
    FILTER(?t NOT IN (sdk:RenewableEnergyIndustry, sdk:UtilitiesIndustry))
  }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?org ?orgLabel
WHERE {
  ?org sdk:suppliesToIndustry ?ind1 .
  ?org sdk:suppliesToIndustry ?ind2 .
  FILTER(?ind1 != ?ind2)
  ?ind1 a sdk:RenewableEnergyIndustry .
  ?ind2 a sdk:UtilitiesIndustry .
  FILTER NOT EXISTS {
    ?org sdk:suppliesToIndustry ?ind3 .
    FILTER(?ind3 != ?ind1 && ?ind3 != ?ind2)
  }
  OPTIONAL { ?org rdfs:label ?orgLabel }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasCertificate ?cert1, ?cert2 .
  ?cert1 a sdk:ISO9001 .
  ?cert2 a sdk:ISO14001 .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel ?productCount
WHERE {
  {
    SELECT ?manufacturer (COUNT(DISTINCT ?product) AS ?productCount)
    WHERE {
      ?manufacturer a iof-core:Manufacturer .
      OPTIONAL { ?manufacturer sdk:manufactures ?product . }
    }
    GROUP BY ?manufacturer
  }
  {
    SELECT (MAX(?c) AS ?maxCount)
    WHERE {
      {
        SELECT ?m (COUNT(DISTINCT ?p) AS ?c)
        WHERE {
          ?m a iof-core:Manufacturer .
          OPTIONAL { ?m sdk:manufactures ?p . }
        }
        GROUP BY ?m
      }
    }
  }
  FILTER (?productCount = ?maxCount)
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel }
}
ORDER BY ?manufacturerLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT ?industryType ?supplierManufacturerCount
WHERE {
  {
    SELECT ?industryType (COUNT(DISTINCT ?m) AS ?supplierManufacturerCount)
    WHERE {
      ?m a iof-core:Manufacturer ;
         sdk:suppliesToIndustry ?industry .
      ?industry a ?industryType .
    }
    GROUP BY ?industryType
  }
  {
    SELECT (MAX(?cnt) AS ?maxCount)
    WHERE {
      SELECT ?industryType (COUNT(DISTINCT ?m) AS ?cnt)
      WHERE {
        ?m a iof-core:Manufacturer ;
           sdk:suppliesToIndustry ?industry .
        ?industry a ?industryType .
      }
      GROUP BY ?industryType
    }
  }
  FILTER(?supplierManufacturerCount = ?maxCount)
}
ORDER BY ?industryType

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?state ?stateLabel ?org ?orgLabel ?headcount
WHERE {
  {
    SELECT ?state (MAX(?hc) AS ?maxHC)
    WHERE {
      ?org a iof-core:Manufacturer ;
           sdk:hasNumberOfEmployees ?n ;
           sdk:organizationLocatedIn ?site .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
      BIND(xsd:integer(REPLACE(STR(?n), "[^0-9]", "")) AS ?hc)
    }
    GROUP BY ?state
  }
  ?org a iof-core:Manufacturer ;
       sdk:hasNumberOfEmployees ?n ;
       sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  OPTIONAL { ?org rdfs:label ?orgLabel . }
  OPTIONAL { ?state rdfs:label ?stateLabel . }
  BIND(xsd:integer(REPLACE(STR(?n), "[^0-9]", "")) AS ?headcount)
  FILTER(?headcount = ?maxHC)
}
ORDER BY ?stateLabel ?orgLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?org ?orgLabel ?totalCapabilities
WHERE {
  ?org a iof-core:Manufacturer .
  {
    SELECT ?org (COUNT(DISTINCT ?cap) AS ?totalCapabilities)
    WHERE {
      { ?org sdk:hasProcessCapability ?cap }
      UNION
      { ?org sdk:hasMaterialCapability ?cap }
    }
    GROUP BY ?org
  }
  OPTIONAL { ?org rdfs:label ?orgLabel }
}
ORDER BY DESC(?totalCapabilities)
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT ?naicsCode ?naicsText (COUNT(DISTINCT ?m) AS ?manufacturerCount)
WHERE {
  ?m a iof-core:Manufacturer ;
     sdk:hasPrimaryNAICSClassifier ?naicsInst .
  ?naicsInst sdk:hasNAICSCodeValue ?naicsCode .
  OPTIONAL { ?naicsInst sdk:hasNAICSTextValue ?naicsText . }
}
GROUP BY ?naicsCode ?naicsText
ORDER BY DESC(?manufacturerCount)
LIMIT 1

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer (SAMPLE(?city) AS ?city) (SAMPLE(?label) AS ?cityLabel)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  OPTIONAL { ?city rdfs:label ?label . }
}
GROUP BY ?manufacturer
ORDER BY ?manufacturer

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel ?coords
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    OPTIONAL {
      ?site sdk:hasSpatialCoordinates ?coord .
      OPTIONAL { ?coord sdk:hasLatitudeValue ?lat . }
      OPTIONAL { ?coord sdk:hasLongitudeValue ?long . }
    }
  }
  BIND(IF(BOUND(?lat) && BOUND(?long), CONCAT(STR(?lat), ",", STR(?long)), "no-coords") AS ?coords)
}
ORDER BY ?manufacturerLabel ?manufacturer

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>

SELECT ?manufacturer (COALESCE(SAMPLE(?zip), SAMPLE(?addr), SAMPLE(?name)) AS ?preferredValue)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?name . }
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    OPTIONAL {
      ?site sdk:hasZIPcode ?zipNode .
      ?zipNode sdk:hasIntegerValue ?zip .
    }
    OPTIONAL {
      ?site sdk:hasPostalAddress ?addrNode .
      ?addrNode iof-scro:hasTextValue ?addr .
    }
  }
}
GROUP BY ?manufacturer
ORDER BY ?manufacturer

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel (GROUP_CONCAT(DISTINCT ?capabilityLabel; separator=" | ") AS ?capabilityNames)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel .
  {
    ?manufacturer sdk:hasProcessCapability ?capability .
  } UNION {
    ?manufacturer sdk:hasMaterialCapability ?capability .
  }
  ?capability rdfs:label ?capabilityLabel .
}
GROUP BY ?manufacturer ?manufacturerLabel
ORDER BY ?manufacturerLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  FILTER (
    EXISTS {
      ?manufacturer sdk:hasProcessCapability ?procCap .
      ?procCap rdfs:label ?procLabel .
      FILTER regex(str(?procLabel), "ing$", "i")
    }
    ||
    EXISTS {
      ?manufacturer sdk:hasMaterialCapability ?matCap .
    }
  )
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?company ?companyLabel ?site ?city ?cityLabel ?state ?stateName
WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?companyLabel ;
           sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state ;
        rdfs:label ?cityLabel .
  ?state rdfs:label ?stateName .
}
ORDER BY ?stateName ?cityLabel ?companyLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?state ?stateLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  ?manufacturer (sdk:organizationLocatedIn/sd k:locatedInCity/sd k:locatedInState | sdk:locatedInState) ?state .
  ?state a sdk:State .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel }
  OPTIONAL { ?state rdfs:label ?stateLabel }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                sdk:hasProcessCapability ?anyCap .
  FILTER NOT EXISTS {
    ?manufacturer sdk:hasProcessCapability ?cap .
    OPTIONAL { ?cap rdfs:label ?capLabel . }
    FILTER(!(BOUND(?capLabel) && REGEX(STR(?capLabel), "ing$", "i")))
  }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }

  ?manufacturer sdk:hasMaterialCapability ?capAllowed .
  ?capAllowed rdfs:label ?capAllowedLabel .
  FILTER(?capAllowedLabel IN ("Urethane","Stainless Steel","Iron","Bronze"))

  FILTER NOT EXISTS {
    ?manufacturer sdk:hasMaterialCapability ?capOther .
    ?capOther rdfs:label ?capOtherLabel .
    FILTER(?capOtherLabel NOT IN ("Urethane","Stainless Steel","Iron","Bronze"))
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?site
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  FILTER NOT EXISTS {
    ?site sdk:hasSpatialCoordinates ?coord .
    ?coord sdk:hasLatitudeValue ?lat ;
           sdk:hasLongitudeValue ?lon .
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label . }
  OPTIONAL { ?manufacturer sdk:hasCertificate ?cert . }
  OPTIONAL { ?manufacturer sdk:manufactures ?prod . }
}
GROUP BY ?manufacturer ?label
HAVING (COUNT(DISTINCT ?cert) >= 1 && COUNT(DISTINCT ?prod) = 0)
ORDER BY ASC(?label)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  FILTER NOT EXISTS {
    ?manufacturer iof-core:describedBy ?desc .
    ?desc iof-scro:hasTextValue ?text .
    FILTER(STRLEN(REPLACE(STR(?text), "^\\s+|\\s+$", "")) > 0)
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer sdk:suppliesToIndustry ?industry . }
  OPTIONAL { ?manufacturer rdfs:label ?label . }
}
GROUP BY ?manufacturer ?label
HAVING (COUNT(DISTINCT ?industry) = 0)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label ?numCertificates
WHERE {
  {
    SELECT ?manufacturer (COUNT(DISTINCT ?cert) AS ?numCertificates)
    WHERE {
      ?manufacturer a iof-core:Manufacturer ;
                    sdk:hasCertificate ?cert .
    }
    GROUP BY ?manufacturer
  }
  OPTIONAL { ?manufacturer rdfs:label ?label . }
  {
    SELECT (AVG(?cnt) AS ?avgCerts)
    WHERE {
      {
        SELECT ?m (COUNT(DISTINCT ?c) AS ?cnt)
        WHERE {
          ?m a iof-core:Manufacturer ;
             sdk:hasCertificate ?c .
        }
        GROUP BY ?m
      }
    }
  }
  FILTER (?numCertificates > ?avgCerts)
}
ORDER BY DESC(?numCertificates)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?industry ?industryLabel ?manufacturer ?manufacturerLabel ?employees ?industryAverage
WHERE {
  {
    SELECT ?industry (AVG(?empNum) AS ?industryAverage)
    WHERE {
      ?m a iof-core:Manufacturer ;
         sdk:suppliesToIndustry ?industry ;
         sdk:hasNumberOfEmployees ?empLit .
      BIND(xsd:integer(REPLACE(STR(?empLit), ",", "")) AS ?empNum)
    }
    GROUP BY ?industry
  }
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?industry ;
                sdk:hasNumberOfEmployees ?empLit2 ;
                rdfs:label ?manufacturerLabel .
  BIND(xsd:integer(REPLACE(STR(?empLit2), ",", "")) AS ?employees)
  ?industry rdfs:label ?industryLabel .
  FILTER(?employees > ?industryAverage)
}
ORDER BY ?industryLabel DESC(?employees)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?state ?stateLabel (AVG(?emp) AS ?avgEmployeeCount)
WHERE {
  {
    SELECT DISTINCT ?m ?state (xsd:integer(REPLACE(STR(?rawEmp), ",", "")) AS ?emp)
    WHERE {
      ?m a iof-core:Manufacturer ;
         sdk:hasNumberOfEmployees ?rawEmp ;
         sdk:organizationLocatedIn ?site ;
         sdk:manufactures ?prod .
      ?prod rdfs:label ?prodLabel .
      FILTER(REGEX(?prodLabel, "[0-9]"))
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
    }
  }
  OPTIONAL { ?state rdfs:label ?stateLabel }
}
GROUP BY ?state ?stateLabel
ORDER BY ?stateLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?state ?stateLabel ?totalProcessCapabilities ?totalMaterialCapabilities
WHERE {
  {
    SELECT DISTINCT ?state WHERE {
      ?m a iof-core:Manufacturer ;
         sdk:organizationLocatedIn ?site .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
    }
  }
  OPTIONAL {
    SELECT ?state (COUNT(DISTINCT ?procPair) AS ?pCount)
    WHERE {
      ?m a iof-core:Manufacturer ;
         sdk:organizationLocatedIn ?site ;
         sdk:hasProcessCapability ?procCap .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
      BIND(CONCAT(STR(?m), "|", STR(?procCap)) AS ?procPair)
    }
    GROUP BY ?state
  }
  OPTIONAL {
    SELECT ?state (COUNT(DISTINCT ?matPair) AS ?mCount)
    WHERE {
      ?m a iof-core:Manufacturer ;
         sdk:organizationLocatedIn ?site ;
         sdk:hasMaterialCapability ?matCap .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
      BIND(CONCAT(STR(?m), "|", STR(?matCap)) AS ?matPair)
    }
    GROUP BY ?state
  }
  OPTIONAL { ?state rdfs:label ?stateLabel }
  BIND(COALESCE(?pCount, 0) AS ?totalProcessCapabilities)
  BIND(COALESCE(?mCount, 0) AS ?totalMaterialCapabilities)
}
ORDER BY ?stateLabel ?state

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?naicsCode ?naicsText ?manufacturerCount ?totalProducts ?avgEmployees
WHERE {
  {
    SELECT ?naicsCode ?naicsText (COUNT(DISTINCT ?m) AS ?manufacturerCount) (AVG(?empNum) AS ?avgEmployees)
    WHERE {
      ?m a iof-core:Manufacturer ;
         sdk:hasPrimaryNAICSClassifier ?naicsInst ;
         sdk:hasNumberOfEmployees ?empLit .
      ?naicsInst sdk:hasNAICSCodeValue ?codeVal .
      OPTIONAL { ?naicsInst sdk:hasNAICSTextValue ?naicsText . }
      BIND(STR(?codeVal) AS ?naicsCode)
      BIND(xsd:integer(REPLACE(STR(?empLit), ",", "")) AS ?empNum)
    }
    GROUP BY ?naicsCode ?naicsText
  }
  OPTIONAL {
    SELECT ?naicsCode (COUNT(DISTINCT ?product) AS ?totalProducts)
    WHERE {
      ?m a iof-core:Manufacturer ;
         sdk:hasPrimaryNAICSClassifier ?naicsInst .
      ?naicsInst sdk:hasNAICSCodeValue ?codeVal .
      BIND(STR(?codeVal) AS ?naicsCode)
      ?m sdk:manufactures ?product .
    }
    GROUP BY ?naicsCode
  }
}
ORDER BY ?naicsCode

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?name
WHERE {
  ?org a iof-core:Manufacturer ;
       rdfs:label ?name .
  FILTER(LANG(?name) = "" || LANGMATCHES(LANG(?name), "en"))
}
ORDER BY LCASE(STR(?name))

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>

SELECT DISTINCT ?manufacturer ?name
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?name . }
  OPTIONAL {
    ?manufacturer iof-core:describedBy ?descNode .
    ?descNode iof-scro:hasTextValue ?descText .
  }
  FILTER (
    (BOUND(?name) && REGEX(STR(?name), "Company", "i")) ||
    (BOUND(?descText) && REGEX(STR(?descText), "Company", "i"))
  )
}
ORDER BY ?manufacturer

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?product ?productLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:manufactures ?product ;
                rdfs:label ?manufacturerLabel .
  ?product a iof-core:MaterialProduct ;
           rdfs:label ?productLabel .
  FILTER(?productLabel IN ("Tube Bending", "Punching"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?org ?orgLabel
WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:hasNumberOfEmployees ?emp ;
       sdk:hasProcessCapability ?cap ;
       sdk:organizationLocatedIn ?site ;
       rdfs:label ?orgLabel .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state rdfs:label ?stateLabel .
  ?cap rdfs:label ?capLabel .
  FILTER (LCASE(STR(?stateLabel)) = "california") .
  FILTER REGEX(STR(?capLabel), "ing$", "i") .
  FILTER ( xsd:integer(REPLACE(STR(?emp), ",", "")) >= 20 )
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?org ?orgLabel WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:suppliesToIndustry ?indRE ;
       sdk:suppliesToIndustry ?indUtil ;
       sdk:hasCertificate ?cert .
  ?indRE a sdk:RenewableEnergyIndustry .
  ?indUtil a sdk:UtilitiesIndustry .
  ?cert a sdk:ISO9001 .
  OPTIONAL { ?org rdfs:label ?orgLabel . }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?city ?cityLabel (AVG(?empNum) AS ?avgEmployeeCount)
WHERE {
  {
    SELECT ?m
    WHERE {
      ?m a iof-core:Manufacturer .
      {
        { ?m sdk:hasProcessCapability ?cap . }
        UNION
        { ?m sdk:hasMaterialCapability ?cap . }
      }
    }
    GROUP BY ?m
    HAVING (COUNT(DISTINCT ?cap) >= 4)
  }
  ?m sdk:hasNumberOfEmployees ?emp ;
     sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  OPTIONAL { ?city rdfs:label ?cityLabel . }
  BIND(xsd:integer(REPLACE(STR(?emp), ",", "")) AS ?empNum)
}
GROUP BY ?city ?cityLabel
ORDER BY ?avgEmployeeCount

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label }

  {
    SELECT ?manufacturer (COUNT(DISTINCT ?prod) AS ?prodCount)
    WHERE {
      ?manufacturer a iof-core:Manufacturer .
      OPTIONAL { ?manufacturer sdk:manufactures ?prod . }
    }
    GROUP BY ?manufacturer
  }

  {
    SELECT ?manufacturer (COUNT(DISTINCT ?pcap) AS ?procCount)
    WHERE {
      ?manufacturer a iof-core:Manufacturer .
      OPTIONAL { ?manufacturer sdk:hasProcessCapability ?pcap . }
    }
    GROUP BY ?manufacturer
  }

  {
    SELECT ?manufacturer (COUNT(DISTINCT ?mcap) AS ?matCount)
    WHERE {
      ?manufacturer a iof-core:Manufacturer .
      OPTIONAL { ?manufacturer sdk:hasMaterialCapability ?mcap . }
    }
    GROUP BY ?manufacturer
  }

  FILTER( (?prodCount = 2) || ((?procCount = 2) && (?matCount = 2)) )
}
